import pandas as pd
import numpy as np
from scipy.stats import pearsonr

# Load the data
df = pd.read_csv('cost_data_with_errors.csv')

# Handle missing values and extract relevant columns
df = df.dropna()
df['dates_active'] = df['dates_active'].str.split('–').str[0]
df['dates_active'] = pd.to_datetime(df['dates_active'])
df['duration'] = (df['dates_active'].dt.year - df['dates_active'].dt.year.shift(-1)).abs()

# Split data based on median damage
median_damage = df['damage_USD'].median()
high_damage = df[df['damage_USD'] > median_damage]
low_damage = df[df['damage_USD'] <= median_damage]

# Calculate correlation and p-value for high damage
r_high, p_high = pearsonr(high_damage['max_storm_cat'], high_damage['duration'])
r_high = round(r_high, 2)
p_high = round(p_high, 4)
if p_high < 0.05:
    if abs(r_high) >= 0.4:
        relationship_type_high = "linear"
    else:
        relationship_type_high = "nonlinear"
else:
    relationship_type_high = "none"

# Calculate correlation and p-value for low damage
r_low, p_low = pearsonr(low_damage['max_storm_cat'], low_damage['duration'])
r_low = round(r_low, 2)
p_low = round(p_low, 4)
if p_low < 0.05:
    if abs(r_low) >= 0.4:
        relationship_type_low = "linear"
    else:
        relationship_type_low = "nonlinear"
else:
    relationship_type_low = "none"

{
